//! 📚️ Completed replay metadata reads exact original Edit slots until each borrowed digest and index row finishes.
use semio_os_store_engine::lifted_store::ArtifactStore;
use semio_os_spr::{Edit,Mutation,OpBinary,OpText};
use semio_os_store_replay::EditReplayResult;
use semio_framework_value::{ToValue,FromValue,ValueError,ArtifactOwnedValueRetirementFactory,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_os_store_ledger::original_replay_metadata::{OriginalReplayMetadata,ReplayMetadataRow};
use semio_os_store_replay_operation::native::history::OriginalHistorySource;
use semio_framework_value::{FactoryAuthority,RetirementDemand,retained_clone::retained_clone_grant_admits};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use std::mem::{ManuallyDrop,size_of};
use std::sync::Arc;

/// 🧳️ Metadata owns its actual roots and source loans independently of unpublished replay payloads.
pub struct OriginalReplayMetadataPreparation<M:Sync>{pub metadata:OriginalReplayMetadata,source:ManuallyDrop<Option<OriginalHistorySource<Edit<M>>>>,issuer:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>>,issuer_close:Option<FactoryAuthority>,frontier:(usize,u64,u64,[u8;32]),ordinal:usize,result_identity:Option<usize>,identity:OriginalIdentityCompare,identity_phase:u8,returning:bool,root_wanted:bool,closing:bool,clear_redo:bool,selected_redo:ManuallyDrop<Option<semio_os_vcs::HistoryPageStack<semio_os_store_ledger::CursorRevisionRecord>>>,redo_row:usize,redo_ready:bool,redo_close:semio_framework_value::retained_clone::RetainedCloneClose,empty_redo:semio_os_vcs::HistoryPageStack<semio_os_store_ledger::CursorRevisionRecord>}
fn invalid(text:&'static str)->ValueError{ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,text)}
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq)]
struct OriginalIdentityCompare{source:Option<(usize,usize,usize,usize)>,offset:usize,complete:bool}
impl OriginalIdentityCompare{
 fn copy_bytes()->usize{2*size_of::<Self>()}
 fn complete(&self)->bool{self.complete}
 fn advance(&mut self,left:&str,right:&str,grant:RetainedCloneGrant,fuel:u64)->semio_framework_value::RetainedWorkOutcome<(bool,RetainedCloneProgress)>{let source=(left.as_ptr()as usize,left.len(),right.as_ptr()as usize,right.len());if self.source.is_some_and(|held|held!=source){return semio_framework_value::RetainedWorkOutcome{result:Err(invalid("original history identity source changed")),work:0}}if self.complete{return semio_framework_value::RetainedWorkOutcome{result:Ok((true,Default::default())),work:0}}if fuel==0||grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<Self::copy_bytes(){return semio_framework_value::RetainedWorkOutcome{result:Ok((false,Default::default())),work:0}}if left.len()!=right.len(){return semio_framework_value::RetainedWorkOutcome{result:Err(invalid("original history identities differ")),work:1}}self.source=Some(source);let p=RetainedCloneProgress{copied_items:1,copied_bytes:Self::copy_bytes(),..Default::default()};if self.offset<left.len(){if left.as_bytes()[self.offset]!=right.as_bytes()[self.offset]{return semio_framework_value::RetainedWorkOutcome{result:Err(invalid("original history identities differ").with_retained_progress(p)),work:1}}self.offset+=1}self.complete=self.offset==left.len();semio_framework_value::RetainedWorkOutcome{result:Ok((self.complete,p)),work:1}}
}
#[cfg(test)]
mod original_identity_tests{
 use super::*;
 #[test]fn original_identity_pages_one_byte_and_refuses_source_substitution(){
  for(left,right,equal)in[("","",true),("edit-λ🙂","edit-λ🙂",true),("edit-a","edit-b",false),("edit","edit-long",false)]{let left=left.to_owned();let right=right.to_owned();let mut cursor=OriginalIdentityCompare::default();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:OriginalIdentityCompare::copy_bytes(),maximum_depth:1,..Default::default()};let denied=cursor.advance(&left,&right,grant,0);assert_eq!(denied.work,0);assert!(!denied.result.unwrap().0);let mut accepted=true;for _ in 0..128{let turn=cursor.advance(&left,&right,grant,1);assert!(turn.work<=1);match turn.result{Ok((done,p))=>{assert!(p.fits(grant));if done{break}},Err(_)=>{accepted=false;break}}}assert_eq!(accepted&&cursor.complete(),equal);}
  let left="original".to_owned();let other=left.clone();let right=left.clone();let mut cursor=OriginalIdentityCompare::default();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:OriginalIdentityCompare::copy_bytes(),maximum_depth:1,..Default::default()};assert!(!cursor.advance(&left,&right,grant,1).result.unwrap().0);let saved=cursor;assert!(cursor.advance(&other,&right,grant,1).result.is_err());assert_eq!(cursor,saved);
 }
}
fn tally<T>(work:&mut u128,turn:semio_framework_value::RetainedWorkOutcome<T>)->Result<T,ValueError>{*work=work.saturating_add(turn.work);turn.result}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn fund(control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant,d:RetirementDemand)->Result<bool,ValueError>{if !retained_clone_grant_admits(grant,d){return Ok(false)}control.admit_turn_capacity(grant.maximum_capacity_bytes)?;control.charge(d.capacity_bytes)?;Ok(true)}
impl<M:Sync> OriginalReplayMetadataPreparation<M>{
 /// 🌱️ The enclosing funded publisher captures the same document identity and source frontier once.
 pub fn new(frontier:(usize,u64,u64,[u8;32]),identity:[u8;32],clear_redo:bool)->Self{Self{metadata:OriginalReplayMetadata::new(identity),source:ManuallyDrop::new(None),issuer:ManuallyDrop::new(None),issuer_close:None,frontier,ordinal:0,result_identity:None,identity:Default::default(),identity_phase:0,returning:false,root_wanted:false,closing:false,clear_redo,selected_redo:ManuallyDrop::new(None),redo_row:0,redo_ready:false,redo_close:Default::default(),empty_redo:semio_os_vcs::HistoryPageStack::empty()}}
 /// 🪃️ A streamed abort rebuilds the applied prefix while preserving the original redo authority.
 pub(crate) fn new_stream_abort(frontier:(usize,u64,u64,[u8;32]),identity:[u8;32])->Self{let mut owner=Self::new(frontier,identity,false);owner.redo_ready=true;owner}
 /// 🏁️ Every original source and issuer must return before the publisher can expose prepared metadata.
 pub fn root_wanted(&self)->bool{self.root_wanted}
 /// 🌱️ The original root read advances inside its own funded effect, never inside a receiving callback.
 pub fn advance_root<P>(&mut self,store:&mut ArtifactStore<P,M>,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>)->Result<RetainedCloneProgress,ValueError>where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{self.validate(store,None)?;let source=self.source.as_mut().ok_or_else(||invalid("replay metadata original source is absent"))?;let turn=source.advance_root(&mut store.log.envelope.vcs.edits,effect);self.root_wanted=false;turn.result.map(|step|step.progress())}
 pub fn prepared(&self)->bool{self.metadata.prepared()&&self.source.is_none()&&self.issuer.is_none()&&self.issuer_close.is_none()&&!self.closing}
 /// 🛑️ Cancellation stops borrowed codecs before returning the original history slots.
 pub fn begin_close(&mut self){self.closing=true;self.returning=true;self.metadata.begin_close();if let Some(source)=self.source.as_mut(){source.begin_close();}}
 /// 🫙️ Terminal ownership includes private metadata, original reads and their captured issuer authority.
 pub fn terminal_is_empty(&self)->bool{self.metadata.terminal_is_empty()&&self.selected_redo.is_none()&&self.redo_close.is_empty()&&self.source.is_none()&&self.issuer.is_none()&&self.issuer_close.is_none()}
}
impl<M:Send+Sync+'static> OriginalReplayMetadataPreparation<M>{
 fn validate<P>(&self,store:&ArtifactStore<P,M>,result:Option<&EditReplayResult<P,M>>)->Result<(),ValueError>where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{let (registry,issuance,generation,revision)=self.frontier;if store.owners.snapshot_read_leases.identity()!=registry||store.log.envelope.vcs.edits.retained_issuance()!=issuance{return Err(invalid("replay metadata requires its original Store and history issuer"))}if let Some(result)=result{if store.cursor.generation!=generation||store.cursor.content_revision!=revision||result.revision!=revision||result.original_history!=Some((registry,issuance)){return Err(invalid("replay metadata original event frontier changed"))}}Ok(())}
 /// 🪡️ One turn retains, digests or returns one genuine original history row under the caller's decoder.
 pub fn advance<P>(&mut self,store:&mut ArtifactStore<P,M>,result:&EditReplayResult<P,M>,control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant,fuel:u64)->semio_framework_value::RetainedWorkOutcome<RetainedCloneProgress>where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{
  self.advance_in_order(store,result,None,control,grant,fuel)
 }
 pub(crate) fn advance_in_order<P>(&mut self,store:&mut ArtifactStore<P,M>,result:&EditReplayResult<P,M>,order:Option<&semio_os_vcs::HistoryPageStack<semio_os_vcs::ArtifactHistoryKey>>,control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant,fuel:u64)->semio_framework_value::RetainedWorkOutcome<RetainedCloneProgress>where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{let mut work=0u128;let result=(||{
  if result.original_order!=order.map(|o|(o as*const _ as usize,o.len())){return Err(invalid("metadata changed its original selected edit order source"))}
  self.validate(store,Some(result))?;if result.original_decode!=control.retirement_recipient_identity().map(|recipient|(control.ledger_identity(),recipient)){return Err(invalid("replay metadata requires its original decoder ledger and recipient"))}if self.closing{return Err(invalid("closing replay metadata cannot resume preparation"))}if self.prepared()||fuel==0{return Ok(Default::default())}
  let result_address=result as *const _ as usize;if self.result_identity.is_some_and(|held|held!=result_address){return Err(invalid("replay metadata changed its original result owner"))}if self.result_identity.is_none(){let d=header::<Option<usize>>();if !fund(control,grant,d)?{return Ok(Default::default())}self.result_identity=Some(result_address);work=1;return Ok(receipt(d))}
  if let Some(selection)=result.original_selection{if !self.redo_ready{if self.selected_redo.is_none(){let d=header::<semio_os_vcs::HistoryPageStack<semio_os_store_ledger::CursorRevisionRecord>>();if !fund(control,grant,d)?{return Ok(Default::default())}*self.selected_redo=Some(semio_os_vcs::HistoryPageStack::empty());work=1;return Ok(receipt(d))}let original=&store.cursor.revision_accumulator.redo;let length=if selection.restoring{original.len().checked_sub(1)}else{original.len().checked_add(1)}.ok_or_else(||invalid("native history redo extent changed"))?;if self.redo_row==length{let d=header::<bool>();if !fund(control,grant,d)?{return Ok(Default::default())}self.redo_ready=true;work=1;return Ok(receipt(d))}let source=if !selection.restoring&&self.redo_row==original.len(){store.cursor.revision_accumulator.applied.get(selection.position)}else{original.get(self.redo_row+usize::from(selection.restoring&&self.redo_row>=selection.redo_position))}.ok_or_else(||invalid("native history original redo record is absent"))?;let target=self.selected_redo.as_mut().unwrap();let d=RetirementDemand{capacity_bytes:target.next_push_allocation_bytes(),..header::<(semio_os_store_ledger::CursorRevisionRecord,usize)>()};if !fund(control,grant,d)?{return Ok(Default::default())}work=1;target.try_push(source.clone()).map_err(|_|invalid("native history prepared redo record refused its original slot"))?;self.redo_row+=1;return Ok(receipt(d))}}
  if self.returning||self.metadata.prepared(){return Ok(Default::default())}
  if self.metadata.ordinal()==result.order.len(){return tally(&mut work,self.metadata.advance::<P,M>(None,if let Some(redo)=self.selected_redo.as_ref(){redo}else if self.clear_redo{&self.empty_redo}else{&store.cursor.revision_accumulator.redo},grant,|_,_,_,_|semio_framework_value::RetainedWorkOutcome{result:Err(invalid("finished metadata cannot request another edit digest")),work:0},|bytes|{control.admit_turn_capacity(grant.maximum_capacity_bytes)?;control.charge(bytes)}))}
  if self.issuer.is_none(){let d=store.history_edit_read_issuer_demands();if !fund(control,grant,d)?{return Ok(Default::default())}work=1;return store.admit_history_edit_read_issuer(&mut self.issuer,grant).map(|step|step.progress())}
  let ordinal=self.metadata.ordinal();let key=if let Some(source)=self.source.as_ref(){if self.ordinal!=ordinal{return Err(invalid("replay metadata original source ordinal changed"))}source.key().ok_or_else(||invalid("replay metadata original source key is absent"))?.key}else if let Some(order)=order{*order.get(ordinal).ok_or_else(||invalid("checkpoint metadata original key is absent"))?}else{store.original_report_key(result.original_selection,ordinal).map_err(|_|invalid("replay metadata original selected ledger key is absent"))?};
  if self.source.is_none(){let read=store.log.envelope.vcs.edits.retained_read_key(key).ok_or_else(||invalid("replay metadata original edit is absent"))?;let d=OriginalHistorySource::<Edit<M>>::constructor_demand();if !fund(control,grant,d)?{return Ok(Default::default())}if let Some((source,p))=OriginalHistorySource::admit(read,store.log.envelope.vcs.edits.retained_read_issuer(read)?.unwrap_or(self.issuer.as_ref().unwrap()),grant)?{*self.source=Some(source);self.ordinal=ordinal;work=1;return Ok(p)}return Ok(Default::default())}
  let source=self.source.as_mut().unwrap();if source.borrow_original().is_err(){let d=source.root_demands(&store.log.envelope.vcs.edits,grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(Default::default())}self.root_wanted=true;return Ok(Default::default())}
  let original=source.borrow_original()?;let edit=original.get();
  if self.identity_phase==0{let lookup=result.order.retained_lookup_work(ordinal).ok_or_else(||invalid("replay metadata original applied edit is absent"))?;if fuel<=lookup||!retained_clone_grant_admits(grant,RetirementDemand{copy_bytes:OriginalIdentityCompare::copy_bytes(),depth:1,..Default::default()}){return Ok(Default::default())}let left=result.order.get(ordinal).ok_or_else(||invalid("replay metadata original applied edit is absent"))?;let turn=self.identity.advance(left,&edit.id,grant,fuel-lookup);work=u128::from(lookup).saturating_add(turn.work);let(done,p)=turn.result?;if done{self.identity=Default::default();self.identity_phase=if ordinal>=result.from{1}else{2};}return Ok(p)}
  let inverse=if ordinal>=result.from{let row=result.rebased_inverse.get(ordinal-result.from).ok_or_else(||invalid("completed replay omitted its original rebased inverse row"))?;if self.identity_phase==1{let turn=self.identity.advance(&row.0,&edit.id,grant,fuel);work=turn.work;let(done,p)=turn.result?;if done{self.identity=Default::default();self.identity_phase=2;}return Ok(p)}&row.1}else{&*edit.inverse};
  let wire=store.log.operation_wire.as_ref().ok_or_else(||invalid("replay metadata original operation codec is absent"))?;
  let p=tally(&mut work,self.metadata.advance::<P,M>(Some(ReplayMetadataRow{ledger_key:key,edit,inverse,supersessions:&result.supersessions,flags:&result.unit_flags,previous_flags:&store.cursor.revision_accumulator.unit_flags}),if let Some(redo)=self.selected_redo.as_ref(){redo}else if self.clear_redo{&self.empty_redo}else{&store.cursor.revision_accumulator.redo},grant,|cursor,edit,inverse,g|wire.advance_history_digest(cursor,edit,inverse,g),|bytes|{control.admit_turn_capacity(grant.maximum_capacity_bytes)?;control.charge(bytes)}))?;
  if self.metadata.ordinal()!=ordinal{self.returning=true;source.begin_close();}Ok(p)})();semio_framework_value::RetainedWorkOutcome{result,work}
 }
fn exit(poll:semio_framework_value::OriginalRetirementPoll)->Result<RetainedCloneStep,semio_framework_value::RetirementPollExit>{match poll{semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn.result.map_err(semio_framework_value::RetirementPollExit::Failed),semio_framework_value::RetainedWorkPoll::Pending{work}=>Err(semio_framework_value::RetirementPollExit::Pending(work))}}
 fn return_source<P>(&mut self,store:&mut ArtifactStore<P,M>,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>,mut fund:impl FnMut(RetirementDemand)->Result<bool,ValueError>)->Result<RetainedCloneStep,semio_framework_value::RetirementPollExit>where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{
  let grant=effect.grant();
  if let Some(source)=self.source.as_mut(){source.begin_close();if source.terminal_is_empty(){let d=header::<(Option<OriginalHistorySource<Edit<M>>>,OriginalIdentityCompare,u8)>();if !fund(d)?{return Ok(RetainedCloneStep::Progress(Default::default()))}self.source.take();self.identity=Default::default();self.identity_phase=0;self.returning=false;effect.performed(1)?;return Ok(RetainedCloneStep::Progress(receipt(d)))}let d=source.close_demands(&store.log.envelope.vcs.edits,grant.maximum_copy_bytes)?;if !fund(d)?{return Ok(RetainedCloneStep::Progress(Default::default()))}return source.close_step(&mut store.log.envelope.vcs.edits,effect).result.map_err(semio_framework_value::RetirementPollExit::from)}
  if let Some(issuer)=self.issuer_close.as_mut(){if issuer.terminal_is_empty(){let d=header::<Option<FactoryAuthority>>();if !fund(d)?{return Ok(RetainedCloneStep::Progress(Default::default()))}self.issuer_close=None;effect.performed(1)?;return Ok(RetainedCloneStep::Progress(receipt(d)))}let d=issuer.demands(grant.maximum_copy_bytes)?;if !fund(d)?{return Ok(RetainedCloneStep::Progress(Default::default()))}return Self::exit(issuer.step(effect.grant().maximum_copy_bytes,effect))}
  if self.issuer.is_some(){let d=header::<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>();if !fund(d)?{return Ok(RetainedCloneStep::Progress(Default::default()))}self.issuer_close=Some(FactoryAuthority::new(self.issuer.take().unwrap()));effect.performed(1)?;return Ok(RetainedCloneStep::Progress(receipt(d)))}
  Ok(RetainedCloneStep::Progress(Default::default()))
 }
 /// 🔙️ True while the original source and issuer must return before the next row or before preparation completes.
 pub fn return_wanted(&self)->bool{self.returning||self.metadata.prepared()}
 /// 🔙️ Returns the original source and issuer inside their own funded effect.
 pub fn return_step<P>(&mut self,store:&mut ArtifactStore<P,M>,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>)->Result<RetainedCloneProgress,semio_framework_value::OriginalRetirementFailure>where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{self.validate(store,None).map_err(semio_framework_value::OriginalRetirementFailure::from)?;let grant=effect.grant();match self.return_source(store,effect,|d|Ok(retained_clone_grant_admits(grant,d))){Ok(step)=>Ok(step.progress()),Err(semio_framework_value::RetirementPollExit::Pending(_))=>Ok(Default::default()),Err(semio_framework_value::RetirementPollExit::Failed(failure))=>Err(failure)}}
 /// 📏️ Quotes the exact next original source return or private metadata close without changing custody.
 pub fn close_demands<P>(&self,store:&ArtifactStore<P,M>,body:usize)->Result<RetirementDemand,ValueError>where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{self.validate(store,None)?;if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(header::<(Option<OriginalHistorySource<Edit<M>>>,OriginalIdentityCompare,u8)>())}else{source.close_demands(&store.log.envelope.vcs.edits,body)}}if let Some(issuer)=self.issuer_close.as_ref(){return if issuer.terminal_is_empty(){Ok(header::<Option<FactoryAuthority>>())}else{issuer.demands(body)}}if self.issuer.is_some(){return Ok(header::<Arc<dyn ArtifactOwnedValueRetirementFactory<Edit<M>>>>())}if !self.redo_close.is_empty(){return self.redo_close.demands(body)}if self.selected_redo.is_some(){return self.redo_close.next_owner_demands::<semio_os_vcs::HistoryPageStack<semio_os_store_ledger::CursorRevisionRecord>>(true,&None,body)}self.metadata.close_demands(body)}
 /// ♻️ Returns original reads before retiring private or displaced metadata through actual admitted turns.
 pub fn close_step<P>(&mut self,store:&mut ArtifactStore<P,M>,control:&mut dyn semio_framework_value::OriginalRetirementControl,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>)->semio_framework_value::OriginalRetirementPoll where P: semio_os_spr::StoreState,M: semio_os_spr::StoreMutationFor<P>{
  let grant=effect.grant();
  let result=(||->Result<RetainedCloneStep,semio_framework_value::RetirementPollExit>{
   self.validate(store,None)?;self.begin_close();
   if self.source.is_some()||self.issuer.is_some()||self.issuer_close.is_some(){return self.return_source(store,effect,|d|{if !retained_clone_grant_admits(grant,d){return Ok(false)}control.charge(d.capacity_bytes)?;Ok(true)})}
   if !self.redo_close.is_empty()||self.selected_redo.is_some(){let d=self.close_demands(store,grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.charge(d.capacity_bytes)?;if !self.redo_close.is_empty(){return Self::exit(self.redo_close.step_granted(effect.grant().maximum_copy_bytes,effect))}return self.redo_close.begin_granted(&mut self.selected_redo,effect).result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(semio_framework_value::RetirementPollExit::from)}
   let d=self.metadata.close_demands(grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.charge(d.capacity_bytes)?;Self::exit(self.metadata.close_step(effect))
  })();
  semio_framework_value::RetirementPollExit::settle(effect,result)
 }
}
impl<M:Sync> Drop for OriginalReplayMetadataPreparation<M>{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"completed replay metadata retains original source or private roots");}}
